    required this.periodEndUtc,
    required this.style,
    required this.title,
  });

  @override
  int get hashCode =>
      durationS.hashCode ^
      periodStartUtc.hashCode ^
      periodEndUtc.hashCode ^
      style.hashCode ^
      title.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is VideoParams &&
          runtimeType == other.runtimeType &&
          durationS == other.durationS &&
          periodStartUtc == other.periodStartUtc &&
          periodEndUtc == other.periodEndUtc &&
          style == other.style &&
          title == other.title;
}

/// Cas d'échec du plan (§3.10) — un cas, un variant, un message traduit.
enum VideoPlanErrorKind {
  /// Durée hors de la liste supportée.
  unsupportedDuration,

  /// Plage vide ou inversée.
  emptyPeriod,

  /// Aucune donnée à animer — souvent parce que les zones privées ont tout
  /// écarté (§3.7).
  nothingToRender,
}

/// Résultat du plan.
class VideoPlanResult {
  /// Cause de l'échec, le cas échéant.
  final VideoPlanErrorKind? error;

  /// Images du plan.
  final List<FrameOutput> frames;

  /// Cadence.
  final int fps;

  const VideoPlanResult({this.error, required this.frames, required this.fps});

  static Future<VideoPlanResult> default_() =>
      RustLib.instance.api.crateApiTimelineVideoPlanResultDefault();

  @override
  int get hashCode => error.hashCode ^ frames.hashCode ^ fps.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is VideoPlanResult &&
          runtimeType == other.runtimeType &&
          error == other.error &&
          frames == other.frames &&
          fps == other.fps;
}

/// Style visuel demandé (§3.5).
enum VideoStyle {
  /// Rendu clair.
  classic,

  /// Rendu sombre.
  night,

  /// Trait seul.
  minimal,
}

/// Arrêt à traiter (§5.1).
class VisitInput {
  /// Identifiant en base, remonté tel quel pour que l'UI puisse agir dessus.
  final PlatformInt64 id;

  /// Arrivée, en millisecondes UTC.
  final PlatformInt64 arrivalTsUtc;

  /// Décalage local à l'arrivée.
  final int arrivalTzOffsetMinutes;

  /// Départ, en millisecondes UTC.
  final PlatformInt64 departureTsUtc;

  /// Décalage local au départ.
  final int departureTzOffsetMinutes;

  /// Latitude.
  final double lat;

  /// Longitude.
  final double lon;

  const VisitInput({
    required this.id,
    required this.arrivalTsUtc,
    required this.arrivalTzOffsetMinutes,
    required this.departureTsUtc,
    required this.departureTzOffsetMinutes,
    required this.lat,
    required this.lon,
  });

  @override
  int get hashCode =>
      id.hashCode ^
      arrivalTsUtc.hashCode ^
      arrivalTzOffsetMinutes.hashCode ^
      departureTsUtc.hashCode ^
      departureTzOffsetMinutes.hashCode ^
      lat.hashCode ^
      lon.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is VisitInput &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          arrivalTsUtc == other.arrivalTsUtc &&
          arrivalTzOffsetMinutes == other.arrivalTzOffsetMinutes &&
          departureTsUtc == other.departureTsUtc &&
          departureTzOffsetMinutes == other.departureTzOffsetMinutes &&
          lat == other.lat &&
          lon == other.lon;
}
